        same(owner,app.nativeCampaign(),"semantic failures keep running campaign");
        var negative=new NativeCampaignV5.Snapshot(c.members(),-1,c.pendingGold(),c.readySlots(),c.curriculum(),c.questFlags(),c.worldPosition(),c.pendingChests());
        fails(()->NativeSaveManager.save(save,replace(original,negative,v,original.encounters()),id,content.maps(),p->p.equals(new WorldPosition(0,0))),"invalid checkpoint cannot replace existing file");check(Arrays.equals(valid,Files.readAllBytes(save)),"failed validated write preserves old bytes");
